sets.map(a=>({...a,departmentId:a.departmentId||'kitchen',area:a.area||'General',checks:a.checks||['opening','closing']})); let mode=localStorage.getItem(MODE_KEY)||'manager'; let session='opening'; let currentIndex=0; let draftValue=0; let draftNote=''; let touchStartX=0; let wheelTouchStartY=0; let wheelLastY=0; let wheelAccumulator=0; let selectedAction=''; let pendingSaveNext=true; let currentCleaningId=''; let deliveryDraft=null; let currentDeliveryId=''; let signatureHasInk=false; let signatureDrawing=false;
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
