  function statusFor(asset,value){if(value<asset.min||value>asset.max)return{label:'Action required',className:'high'};return{label:'Within range',className:'ok'}}
  function showPage(name){$$('[data-page]').forEach(p=>p.classList.toggle('active',p.dataset.page===name));$$('[data-target]').forEach(b=>b.classList.toggle('active',b.dataset.target===name));}
  function setMode(next){mode=next;localStorage.setItem(MODE_KEY,mode);$('#appShell').dataset.mode=mode;$('#modeChipLabel').textContent=`${mode[0].toUpperCase()+mode.slice(1)} preview`;$('#workspaceSubtitle').textContent=mode==='manager'?'Manager control centre':`${mode[0].toUpperCase()+mode.slice(1)} workspace`;$('#modeMenu').classList.remove('open');showPage(mode==='manager'?'dashboard':mode)}
  const cleaningBucket=()=>{const d=todayKey();state.cleaningRecords[d]??={};return state.cleaningRecords[d]};
  function cleaningTaskDueToday(t){const now=new Date(),day=now.getDay(),date=now.getDate();if(t.repeat==='once')return t.startDate===todayKey();if(t.repeat==='weekdays')return (t.weekdays||[]).includes(day);if(t.repeat==='weekly')return day===Number(t.weekday??1);if(t.repeat==='monthly')return date===Number(t.monthDay||1);if(t.repeat==='yearly'){const d=new Date(t.startDate||todayKey());return d.getDate()===date&&d.getMonth()===now.getMonth()}if(t.repeat==='custom'){const start=new Date(t.startDate||todayKey());const diff=Math.floor((new Date(todayKey())-new Date(start.toISOString().slice(0,10)))/86400000);return diff>=0&&diff%Math.max(1,Number(t.intervalDays||1))===0}return true}
