  function renderCleaningList(){syncCleaningIssues();const open=openCleaningTasks(),total=scheduledCleaningTasks().length,done=total-open.length;$('#cleaningProgressText').textContent=`${done} / ${total}`;$('#cleaningProgressFill').style.width=`${total?done/total*100:100}%`;const renderGroup=(bucket,target)=>{const tasks=open.filter(t=>t.bucket===bucket);$(target).innerHTML=tasks.map(t=>`<button class="cleaning-task-card ${bucket==='overdue'?'is-overdue':''}" data-cleaning-task="${escapeHtml(t.id)}"><span class="progress-circle"></span><span><strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(t.area)} · ${escapeHtml(t.due)}</small></span><em>›</em></button>`).join('');return tasks.length};const today=renderGroup('today','#todayCleaningTasks'),overdue=renderGroup('overdue','#overdueCleaningTasks');$('#todayCleaningCount').textContent=`${today} open`;$('#overdueCleaningCount').textContent=`${overdue} overdue`;$('.overdue-group').hidden=overdue===0;$('.cleaning-group').hidden=today===0;$('#cleaningEmpty').hidden=open.length!==0;$$('[data-cleaning-task]').forEach(b=>b.onclick=()=>openCleaningDetail(b.dataset.cleaningTask));renderModules('kitchen');renderModules('service');updateManager()}
  function openCleaningDetail(id){const task=state.cleaningTasks.find(t=>t.id===id);if(!task)return;currentCleaningId=id;signatureHasInk=false;$('#cleaningDetailPriority').textContent=task.bucket==='overdue'?'Overdue':'To Do Today';$('#cleaningDetailPriority').classList.toggle('danger-text',task.bucket==='overdue');$('#cleaningDetailTitle').textContent=task.title;$('#cleaningDetailArea').textContent=task.area;$('#cleaningDetailInstructions').textContent=task.instructions;$('#cleaningDetailDue').textContent=task.due;$('#cleaningStaff').innerHTML='<option value="">Select staff member</option>'+state.staff.map(x=>`<option>${escapeHtml(x)}</option>`).join('');$('#cleaningStaff').value='';$('#cleaningNote').value='';$('#cleaningPhoto').value='';$('#cleaningPhotoLabel').textContent='Optional';clearSignaturePad();validateCleaning();showPage('cleaning-detail')}
