  function clearSignaturePad(){const c=$('#signaturePad'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);signatureHasInk=false;validateCleaning()}
  function confirmCleaningTask(){const task=state.cleaningTasks.find(t=>t.id===currentCleaningId);if(!task||!$('#cleaningStaff').value||!signatureHasInk)return;const staff=$('#cleaningStaff').value,now=new Date();cleaningBucket()[task.id]={staff,note:$('#cleaningNote').value.trim(),photo:$('#cleaningPhoto').files.length>0,signature:true,time:now.toISOString()};addAudit('cleaning','confirmed',task.id,{staff,photo:$('#cleaningPhoto').files.length>0,note:$('#cleaningNote').value.trim(),bucket:task.bucket});syncCleaningIssues();save();$('#cleaningSuccessTitle').textContent=task.title;$('#cleaningSuccessMeta').textContent=`Completed by ${staff} · ${now.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;$('#cleaningSuccess').hidden=false;setTimeout(()=>{$('#cleaningSuccess').hidden=true;showPage('cleaning-list');renderCleaningList()},650)}

